import{_ as t,o,c as a,a0 as r}from"./chunks/framework.C3yZ6M33.js";const p=JSON.parse('{"title":"MCP server","description":"","frontmatter":{},"headers":[],"relativePath":"reference/mcp.md","filePath":"reference/mcp.md"}'),d={name:"reference/mcp.md"};function n(s,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-server" tabindex="-1">MCP server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP server&quot;">​</a></h1><p><code>peregrin-mcp</code> is an MCP stdio server — newline-delimited JSON-RPC — that exposes the campaign plane and bundle verbs to agents. Every tool is a thin wrapper over the same library composition the <code>peregrin</code> CLI drives. The server is <strong>advisory</strong>: coordination and claims belong to <a href="https://github.com/9aia/sturn" target="_blank" rel="noreferrer">sturn</a>, not to MCP tool calls.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>campaign_run</code></td><td>Load a workflow file (or an installed bundle&#39;s <code>main.yaml</code>) and run it on this machine&#39;s campaign plane</td></tr><tr><td><code>validate</code></td><td>Load + validate a workflow file — parse, expansion, normalization errors plus wiring warnings</td></tr><tr><td><code>bundle_install</code></td><td>Install a bundle ref (<code>./path</code>, <code>git:&lt;url&gt;[//subdir][#rev]</code>, <code>http(s)</code> <code>.tgz</code>) into the store</td></tr><tr><td><code>bundle_remove</code></td><td>Drop an installed bundle&#39;s store entry (fetch cache untouched)</td></tr><tr><td><code>bundle_list</code></td><td>List installed bundles — <code>name@version</code>, resolved sha, source ref</td></tr><tr><td><code>bundle_info</code></td><td>A bundle&#39;s manifest, provenance, and size</td></tr><tr><td><code>runs</code></td><td>Scan a dir for JSONL run logs and summarize each</td></tr><tr><td><code>events</code></td><td>Tail events from a JSONL run log, optionally filtered by type</td></tr><tr><td><code>explain</code></td><td>Summarize one run log — verdict, per-source counts, failures, duration</td></tr></tbody></table><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>Ctx</code> derives its roots from <code>PEREGRIN_HOME</code>/<code>PEREGRIN_CACHE</code>/XDG — the same store/cache layout the CLI&#39;s distribution env uses. The <code>bundle_*</code> tools currently drive the pinned pre-provider tamias deps directly (fs/git/http sources + local store); they are the MCP surface&#39;s own copy of the install pipeline, not a <code>tamias</code> CLI shell-out.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./campaign-schema.html">Campaign schema</a> — what <code>validate</code>/<code>campaign_run</code> load</li><li><a href="./queue-supersede.html">Queue &amp; supersede</a> — run semantics <code>campaign_run</code> gets</li><li><a href="./distribution.html">Distribution</a> — the ref grammar <code>bundle_install</code> accepts</li></ul>',8)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
